00054 class SEI
00055 {
00056 public:
00057   enum PayloadType
00058   {
00059     BUFFERING_PERIOD                     = 0,
00060     PICTURE_TIMING                       = 1,
00061     FILLER_PAYLOAD                       = 3,
00062     USER_DATA_REGISTERED_ITU_T_T35       = 4,
00063     USER_DATA_UNREGISTERED               = 5,
00064     FILM_GRAIN_CHARACTERISTICS           = 19,
00065     FRAME_PACKING                        = 45,
00066     PARAMETER_SETS_INCLUSION_INDICATION  = 129,
00067     DECODING_UNIT_INFO                   = 130,
00068     DECODED_PICTURE_HASH                 = 132,
00069     SCALABLE_NESTING                     = 133,
00070     MASTERING_DISPLAY_COLOUR_VOLUME      = 137,
00071     DEPENDENT_RAP_INDICATION             = 145,
00072     EQUIRECTANGULAR_PROJECTION           = 150,
00073     SPHERE_ROTATION                      = 154,
00074     REGION_WISE_PACKING                  = 155,
00075     OMNI_VIEWPORT                        = 156,
00076     GENERALIZED_CUBEMAP_PROJECTION       = 153,
00077     FRAME_FIELD_INFO                     = 168,
00078     SUBPICTURE_LEVEL_INFO                = 203,
00079     SAMPLE_ASPECT_RATIO_INFO             = 204,
00080     CONTENT_LIGHT_LEVEL_INFO             = 144,
00081     ALTERNATIVE_TRANSFER_CHARACTERISTICS = 147,
00082     AMBIENT_VIEWING_ENVIRONMENT          = 148,
00083     CONTENT_COLOUR_VOLUME                = 149,
00084   };
00085 
00086   SEI() {}
00087   virtual ~SEI() {}
00088 
00089   static const char *getSEIMessageString(SEI::PayloadType payloadType);
00090 
00091   virtual PayloadType payloadType() const = 0;
00092 };
